import pytest


def shipping_fee(weight_kg, zone=None):
    """Calculate shipping fee by weight and zone."""
    if weight_kg <= 1:
        fee = 8
    elif weight_kg <= 5:
        fee = 8 + (weight_kg - 1) * 3
    else:
        fee = 8 + 4 * 3 + (weight_kg - 5) * 2
        fee = min(fee, 45)

    if zone == 'remote':
        fee *= 1.5

    return fee


class TestShippingFee:
    @pytest.mark.parametrize('weight_kg,zone,expected', [
        (0.5, None, 8),           # base price
        (3, None, 14),            # 8 + (3-1)*3
        (8, None, 26),            # 8 + 4*3 + 3*2
        (8, 'remote', 39),        # 26 * 1.5
    ])
    def test_calculates_correct_fee(self, weight_kg, zone, expected):
        assert shipping_fee(weight_kg, zone) == expected
